            Game.AddLineToConversation(HLStyleConversationIndex, "TEXT_QST_048_BARRELMAN_OVERHEAR", false, Me, CScriptThing());
        }
    }
    if (IsActiveThreadTerminating()) return _Fail_Val.Return();
}

